using System.ComponentModel;
using System.Windows;using System.Windows.Input;using RAWSelectionAssistant.ViewModels;
namespace RAWSelectionAssistant.Views;
public partial class InstantV3Editor:System.Windows.Controls.UserControl
{
 public static readonly DependencyProperty SectionProperty=DependencyProperty.Register(nameof(Section),typeof(string),typeof(InstantV3Editor),new PropertyMetadata("Full",(d,_)=>((InstantV3Editor)d).RefreshSections()));
 public string Section{get=>(string)GetValue(SectionProperty);set=>SetValue(SectionProperty,value);}
 public InstantV3Editor(){InitializeComponent();RefreshSections();DataContextChanged+=(_,e)=>{if(e.OldValue is ReferenceColorWorkspaceViewModel old)PropertyChangedEventManager.RemoveHandler(old,ResourcesChanged,string.Empty);if(e.NewValue is ReferenceColorWorkspaceViewModel next)PropertyChangedEventManager.AddHandler(next,ResourcesChanged,string.Empty);ApplyFilter();QueuePaperPreviews();};Loaded+=(_,_)=>QueuePaperPreviews();Unloaded+=(_,_)=>paperRefresh.Stop();}
 private readonly System.Windows.Threading.DispatcherTimer paperRefresh=new(){Interval=TimeSpan.FromMilliseconds(200)};
 private bool paperRefreshAttached;
 private void ScheduleGallery(){if(Section is "Advanced" or "Defects")return;if(DataContext is ReferenceColorWorkspaceViewModel vm)vm.InvalidatePaperGallery();if(!paperRefreshAttached){paperRefreshAttached=true;paperRefresh.Tick+=(_,_)=>{if(!IsVisible||DataContext is not ReferenceColorWorkspaceViewModel active){paperRefresh.Stop();return;}if(active.IsLoading||active.IsExporting||active.IsInstantGenerating){paperRefresh.Stop();return;}if(!active.PreviewPhotographerPapersCommand.CanExecute(null))return;paperRefresh.Stop();active.PreviewPhotographerPapersCommand.Execute(null);};}paperRefresh.Stop();paperRefresh.Start();}
 private void ResourcesChanged(object? sender,PropertyChangedEventArgs e){if(e.PropertyName is nameof(ReferenceColorWorkspaceViewModel.PhotographerPapers) or nameof(ReferenceColorWorkspaceViewModel.FilteredFilmPapers))ApplyFilter();if(e.PropertyName is nameof(ReferenceColorWorkspaceViewModel.ActiveTarget) or nameof(ReferenceColorWorkspaceViewModel.IsLoading))QueuePaperPreviews();if(e.PropertyName is {} name&&(name==nameof(ReferenceColorWorkspaceViewModel.SelectedInstantProfile)||name==nameof(ReferenceColorWorkspaceViewModel.SelectedLightPrintFrameId)||name==nameof(ReferenceColorWorkspaceViewModel.InstantInputMode)||name.StartsWith("InstantV3",StringComparison.Ordinal)&&name is not("InstantV3Stocks" or "InstantV3Patterns" or "InstantV3DefectKinds")))ScheduleGallery();}
 private void QueuePaperPreviews(){if(Section is "Advanced" or "Defects")return;Dispatcher.BeginInvoke(new Action(()=>{if(Section is not("Advanced" or "Defects")&&DataContext is ReferenceColorWorkspaceViewModel vm&&vm.PhotographerPapers.Any(p=>p.Preview is null)&&vm.PreviewPhotographerPapersCommand.CanExecute(null))vm.PreviewPhotographerPapersCommand.Execute(null);}));}
 private bool applyingResourceFilter;
 public void SetResourceFilter(string search,string filter){if(DataContext is ReferenceColorWorkspaceViewModel vm){vm.SetFilmResourceFilter(search,filter);ApplyFilter();}}
 private void ApplyFilter(){if(DataContext is not ReferenceColorWorkspaceViewModel vm)return;applyingResourceFilter=true;try{var selected=vm.SelectedPhotographerPaperId;var view=System.Windows.Data.CollectionViewSource.GetDefaultView(vm.FilteredFilmPapers);view.GroupDescriptions.Clear();view.GroupDescriptions.Add(new System.Windows.Data.PropertyGroupDescription("Group"));PaperChoices.ItemsSource=view;PaperChoices.SelectedValue=selected;}finally{applyingResourceFilter=false;}}
 private void PaperSelectionChanged(object sender,System.Windows.Controls.SelectionChangedEventArgs e){if(!applyingResourceFilter&&DataContext is ReferenceColorWorkspaceViewModel vm&&e.AddedItems.OfType<PhotographerPaper>().FirstOrDefault() is{} paper){vm.RecordR53Resource("paper:"+paper.ProfileId);}}
 private void FavoriteLoaded(object sender,RoutedEventArgs e){if(DataContext is ReferenceColorWorkspaceViewModel vm&&sender is System.Windows.Controls.Button{Tag:string id} button)button.Content=vm.IsFilmResourceFavorite("paper:"+id)?"★":"☆";}
 private void ToggleFavorite(object sender,RoutedEventArgs e){if(DataContext is ReferenceColorWorkspaceViewModel vm&&sender is FrameworkElement{Tag:string id}){vm.FavoriteFilmResource("paper:"+id);if(sender is System.Windows.Controls.Button button)button.Content=vm.IsFilmResourceFavorite("paper:"+id)?"★":"☆";ApplyFilter();}}
 private void RefreshSections(){if(PickerArea is null||AdvancedArea is null||FullCommonArea is null)return;FullCommonArea.Visibility=Section=="Full"?Visibility.Visible:Visibility.Collapsed;PickerArea.Visibility=Section is "Advanced" or "Defects"?Visibility.Collapsed:Visibility.Visible;AdvancedArea.Visibility=Section=="Picker"?Visibility.Collapsed:Visibility.Visible;foreach(var expander in AdvancedArea.Children.OfType<System.Windows.Controls.Expander>())expander.Visibility=Section=="Defects"?(ReferenceEquals(expander,DefectsAdvanced)?Visibility.Visible:Visibility.Collapsed):Section=="Advanced"&&ReferenceEquals(expander,DefectsAdvanced)?Visibility.Collapsed:Visibility.Visible;if(Section=="Defects")DefectsAdvanced.IsExpanded=true;}
 private void PaperClicked(object sender,MouseButtonEventArgs e){if(DataContext is ReferenceColorWorkspaceViewModel vm){if(PaperChoices.SelectedValue is string id)vm.SelectFilmPaper(id);ApplyFilter();}}
}
